class Solution {
    using ll = long long;

    int n;
    vector<int> a;
    vector<vector<int>> st;
    vector<int> lg;

    int rangeGcd(int l, int r) {
        if (l > r) return 0;

        int len = r - l + 1;
        int k = lg[len];

        return gcdValue(
            st[k][l],
            st[k][r - (1 << k) + 1]
        );
    }

    int gcdValue(int x, int y) {
        while (y) {
            int t = x % y;
            x = y;
            y = t;
        }
        return x;
    }

    // GCD of the first 'len' elements
    // after removing index 'skip'.
    int prefixGcd(int skip, int len) {
        if (len == 0) return 0;

        if (len <= skip)
            return rangeGcd(0, len - 1);

        return gcdValue(
            rangeGcd(0, skip - 1),
            rangeGcd(skip + 1, len)
        );
    }

    // GCD of elements starting at 'len'
    // in the array after removal.
    int suffixGcd(int skip, int len) {
        int m = n - 1;

        if (len >= m) return 0;

        if (len < skip)
            return gcdValue(
                rangeGcd(len, skip - 1),
                rangeGcd(skip + 1, n - 1)
            );

        return rangeGcd(len + 1, n - 1);
    }

    int countValid(int skip) {
        int m = n - 1;

        if (m < 2) return 0;

        int total = gcdValue(
            rangeGcd(0, skip - 1),
            rangeGcd(skip + 1, n - 1)
        );

        // Find earliest prefix length whose GCD
        // equals the total GCD.
        int lo = 1, hi = m;

        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;

            if (prefixGcd(skip, mid) == total)
                hi = mid;
            else
                lo = mid + 1;
        }

        int first = lo;

        // Find latest prefix length whose suffix
        // GCD equals the total GCD.
        lo = 0;
        hi = m - 1;

        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;

            if (suffixGcd(skip, mid) == total)
                lo = mid;
            else
                hi = mid - 1;
        }

        int last = lo;

        // Valid split prefix lengths are in
        // [first, last], restricted to [1, m-1].
        return max(0, last - first + 1);
    }

public:
    int maxValidSplits(vector<int>& nums) {
        a = nums;
        n = (int)a.size();

        lg.assign(n + 1, 0);

        for (int i = 2; i <= n; ++i)
            lg[i] = lg[i / 2] + 1;

        int K = lg[n] + 1;

        st.assign(K, vector<int>(n));

        st[0] = a;

        for (int k = 1; k < K; ++k) {
            int len = 1 << k;

            for (int i = 0; i + len <= n; ++i) {
                st[k][i] = gcdValue(
                    st[k - 1][i],
                    st[k - 1][i + (len >> 1)]
                );
            }
        }

        // Case 1: No removal.
        int total = rangeGcd(0, n - 1);

        int ans = 0;

        for (int i = 0; i < n - 1; ++i) {
            if (rangeGcd(0, i) == total &&
                rangeGcd(i + 1, n - 1) == total) {
                ++ans;
            }
        }

        // Case 2: Remove exactly one element.
        for (int skip = 0; skip < n; ++skip) {
            ans = max(ans, countValid(skip));
        }

        return ans;
    }
};
